import { useEffect, useState } from "react";
import { api } from "../api/manuscriptApi";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function ManuscriptForm({ method }) {
  const { id } = useParams();
  const navigate = useNavigate();

  const [authors, setAuthors] = useState([]);
  const [loading, setLoading] = useState(true);

  const [form, setForm] = useState({
    title: "",
    abstract: "",
    keywords: "",
    reference_list: "",
    cover_letter: "",
    manuscript_file: null,
    supplementary_materials: [],
    plagiarism_score: 0,
    author_id: "",
    journal_id: "",
    assigned_editor_id: "",
    status: "Submitted",
  });

  /** ----------------------------------------------------
   * LOAD AUTHORS (ROLE FILTERED)
   -----------------------------------------------------*/
  useEffect(() => {
    axios
      .get("http://localhost:5000/api/users?role=Author")
      .then((res) => setAuthors(res.data))
      .catch((err) => console.error("Error loading authors", err));
  }, []);

  /** ----------------------------------------------------
   * LOAD DATA IF EDIT MODE
   -----------------------------------------------------*/
  useEffect(() => {
    if (method === "edit" && id) {
      api.get(`/${id}`).then((res) => {
        const m = res.data;

        setForm({
          ...form,
          title: m.title || "",
          abstract: m.abstract || "",
          keywords: m.keywords?.join(",") || "",
          reference_list: m.reference_list || "",
          cover_letter: m.cover_letter || "",
          plagiarism_score: m.plagiarism_score || 0,
          author_id: m.author_id || "",
          journal_id: m.journal_id || "",
          assigned_editor_id: m.assigned_editor_id || "",
          status: m.status || "Submitted",
          supplementary_materials: [], // reset new uploads
        });

        setLoading(false);
      });
    } else {
      setLoading(false);
    }
  }, [method, id]);

  /** ----------------------------------------------------
   * SUBMIT FORM
   -----------------------------------------------------*/
  const handleSubmit = async (e) => {
    e.preventDefault();

    // simple validation
    if (!form.author_id) return alert("Please select an author.");
    if (!form.journal_id) return alert("Journal ID is required.");

    const fd = new FormData();

    // Append normal fields
    fd.append("title", form.title);
    fd.append("abstract", form.abstract);
    fd.append("keywords", form.keywords);
    fd.append("reference_list", form.reference_list);
    fd.append("cover_letter", form.cover_letter);
    fd.append("plagiarism_score", form.plagiarism_score);
    fd.append("author_id", form.author_id);
    fd.append("journal_id", form.journal_id);
    fd.append("assigned_editor_id", form.assigned_editor_id);
    fd.append("status", form.status);

    // Append main manuscript file
    if (form.manuscript_file) {
      fd.append("manuscript_file", form.manuscript_file);
    }

    // Append supplementary files
    if (form.supplementary_materials.length > 0) {
      Array.from(form.supplementary_materials).forEach((file) =>
        fd.append("supplementary_materials", file)
      );
    }

    try {
      if (method === "create") {
        await api.post("/", fd);
      } else {
        await api.put(`/${id}`, fd);
      }

      navigate("/journal/list");
    } catch (err) {
      console.error("Submit error:", err);
      alert("Error submitting manuscript. Please check console.");
    }
  };

  /** ----------------------------------------------------
   * LOADING STATE
   -----------------------------------------------------*/
  if (loading) return <div className="text-center mt-5">Loading...</div>;

  return (
    <div className="container mt-5">
      <div className="card shadow-lg p-4">
        <h3 className="mb-4 text-primary fw-bold">
          {method === "create" ? "Create New Manuscript" : "Edit Manuscript"}
        </h3>

        <form onSubmit={handleSubmit}>
          <div className="row g-4">
            {/* Title */}
            <div className="col-12">
              <label className="form-label fw-semibold">Manuscript Title</label>
              <input
                className="form-control"
                value={form.title}
                onChange={(e) => setForm({ ...form, title: e.target.value })}
                required
              />
            </div>

            {/* Abstract */}
            <div className="col-12">
              <label className="form-label fw-semibold">Abstract</label>
              <textarea
                className="form-control"
                rows={4}
                value={form.abstract}
                onChange={(e) => setForm({ ...form, abstract: e.target.value })}
                required
              ></textarea>
            </div>

            {/* Keywords */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Keywords</label>
              <input
                className="form-control"
                placeholder="comma separated"
                value={form.keywords}
                onChange={(e) => setForm({ ...form, keywords: e.target.value })}
              />
            </div>

            {/* Plagiarism Score */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Plagiarism Score (%)</label>
              <input
                type="number"
                className="form-control"
                value={form.plagiarism_score}
                onChange={(e) =>
                  setForm({ ...form, plagiarism_score: e.target.value })
                }
              />
            </div>

            {/* Reference List */}
            <div className="col-12">
              <label className="form-label fw-semibold">Reference List</label>
              <textarea
                className="form-control"
                rows={3}
                value={form.reference_list}
                onChange={(e) =>
                  setForm({ ...form, reference_list: e.target.value })
                }
              ></textarea>
            </div>

            {/* Cover Letter */}
            <div className="col-12">
              <label className="form-label fw-semibold">Cover Letter</label>
              <textarea
                className="form-control"
                rows={3}
                value={form.cover_letter}
                onChange={(e) =>
                  setForm({ ...form, cover_letter: e.target.value })
                }
              ></textarea>
            </div>

            {/* Author Dropdown */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Select Author</label>
              <select
                className="form-select"
                value={form.author_id}
                onChange={(e) => setForm({ ...form, author_id: e.target.value })}
                required
              >
                <option value="">Choose...</option>
                {authors.map((author) => (
                  <option key={author.id} value={author.id}>
                    {author.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Journal ID */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Journal ID</label>
              <input
                type="number"
                className="form-control"
                value={form.journal_id}
                onChange={(e) => setForm({ ...form, journal_id: e.target.value })}
                required
              />
            </div>

            {/* Assigned Editor */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Assigned Editor ID</label>
              <input
                type="number"
                className="form-control"
                value={form.assigned_editor_id}
                onChange={(e) =>
                  setForm({ ...form, assigned_editor_id: e.target.value })
                }
              />
            </div>

            {/* Manuscript File */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">
                Upload Manuscript (.pdf/.doc/.docx)
              </label>
              <input
                type="file"
                className="form-control"
                accept=".pdf,.doc,.docx"
                onChange={(e) =>
                  setForm({ ...form, manuscript_file: e.target.files[0] })
                }
                required={method === "create"}
              />
            </div>

            {/* Supplementary Files */}
            <div className="col-12">
              <label className="form-label fw-semibold">Supplementary Materials</label>
              <input
                type="file"
                multiple
                className="form-control"
                onChange={(e) =>
                  setForm({ ...form, supplementary_materials: e.target.files })
                }
              />
            </div>

            {/* Status */}
            <div className="col-md-6">
              <label className="form-label fw-semibold">Manuscript Status</label>
              <select
                className="form-select"
                value={form.status}
                onChange={(e) => setForm({ ...form, status: e.target.value })}
              >
                <option>Submitted</option>
                <option>Under Review</option>
                <option>Revision Requested</option>
                <option>Revision Submitted</option>
                <option>Accepted</option>
                <option>Published</option>
                <option>Desk Reject</option>
              </select>
            </div>

            {/* Submit */}
            <div className="col-12 mt-3">
              <button className="btn btn-primary btn-lg w-100">
                Save Manuscript
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
